<template><div><el-button v-hasPermi="['todo:definition:edit']" type="primary" size="mini" @click="$refs.dialog.show({})">新增触发规则</el-button><el-table :data="rows"><el-table-column prop="event_type" label="事件"/><el-table-column prop="template_name" label="模板"/><el-table-column prop="business_type" label="业务类型"/><el-table-column label="启用" width="100"><template slot-scope="scope"><el-switch :value="scope.row.enabled === 'Y'" @change="toggle(scope.row, $event)" /></template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="scope"><el-button v-hasPermi="['todo:definition:edit']" type="text" @click="$refs.dialog.show(scope.row)">编辑</el-button></template></el-table-column></el-table><trigger-rule-dialog ref="dialog" :templates="templates" @save="save" /></div></template>
<script>
import TriggerRuleDialog from './TriggerRuleDialog'
import { saveTriggerRule } from '@/api/todo-definition'
import { field, triggerPayload } from '../resource-contract'
export default { name: 'TriggerRuleTable', components: { TriggerRuleDialog }, props: { rows: { type: Array, default: () => [] }, templates: { type: Array, default: () => [] } }, methods: { async save(data) { await saveTriggerRule(data); await this.$emit('reload') }, async toggle(row, enabled) { const condition = field(row, 'condition_json', 'conditionJson'); await saveTriggerRule(triggerPayload({ ...row, enabled, event: { eventType: field(row, 'event_type', 'eventType'), payloadVersion: field(row, 'payload_version', 'payloadVersion') || 1, condition: condition ? JSON.parse(condition) : {} } })); await this.$emit('reload') } } }
</script>
